// Generated by Cypress Author on 2026-10-19
//
// ADM 02 (P0) — Plano_de_Testes_QA_MatchWallet.md §12.
// Os contadores vêm de GET /dashboard/admin (cálculo no backend). A tela deve refletir
// exatamente cada estado do fechamento e a competência a que ele pertence.

function dashboard(mesReferencia: string, versoes: number, relatorios: number, pendente: boolean) {
  return {
    totalInvestidores: 10,
    distribuicaoPerfis: {
      CONSERVADOR: 2,
      MODERADO: 3,
      ARROJADO: 2,
      SOFISTICADO: 1,
      SEM_AVALIACAO: 2,
    },
    carteirasAtivas: 3,
    fechamentoMesAtual: {
      mesReferencia,
      versoesPublicadas: versoes,
      relatoriosGerados: relatorios,
      pendente,
    },
  }
}

const ESTADOS = [
  {
    titulo: 'nenhuma carteira fechada (0/3)',
    dados: dashboard('2026-10', 0, 0, true),
    versoes: '0 de 3',
    relatorios: '0 de 3',
    nota: 'Fechamento pendente',
  },
  {
    titulo: 'uma carteira publicada e com relatório (1/3)',
    dados: dashboard('2026-10', 1, 1, true),
    versoes: '1 de 3',
    relatorios: '1 de 3',
    nota: 'Fechamento pendente',
  },
  {
    titulo: 'todas fechadas (3/3)',
    dados: dashboard('2026-10', 3, 3, false),
    versoes: '3 de 3',
    relatorios: '3 de 3',
    nota: 'Fechamento concluído',
  },
]

describe('Plano QA · Painel administrativo — fechamento', () => {
  beforeEach(() => {
    cy.bloquearApi()
    cy.stubSessao('admin')
  })

  for (const estado of ESTADOS) {
    it(`ADM 02 · ${estado.titulo} → checklist e indicadores mostram o progresso da competência`, () => {
      cy.stubApi('GET', '/dashboard/admin', estado.dados, 'dashboard')
      cy.visit('/admin')
      cy.wait('@dashboard')

      cy.contains('Competência 2026-10').should('be.visible')
      cy.get('ul[aria-labelledby="checklist-fechamento"]')
        .contains('li', 'Versões publicadas')
        .should('contain.text', estado.versoes)
      cy.get('ul[aria-labelledby="checklist-fechamento"]')
        .contains('li', 'Relatórios gerados')
        .should('contain.text', estado.relatorios)
      cy.contains(estado.nota).should('be.visible')
    })
  }

  it('ADM 02 · nova competência sem fechamento → zera o progresso e não herda o mês anterior', () => {
    cy.stubApi('GET', '/dashboard/admin', dashboard('2026-11', 0, 0, true), 'dashboard')
    cy.visit('/admin')
    cy.wait('@dashboard')

    cy.contains('Competência 2026-11').should('be.visible')
    cy.contains('Competência 2026-10').should('not.exist')
    cy.get('ul[aria-labelledby="checklist-fechamento"]')
      .contains('li', 'Versões publicadas')
      .should('contain.text', '0 de 3')
    cy.get('ul[aria-labelledby="checklist-fechamento"]')
      .contains('li', 'Relatórios gerados')
      .should('contain.text', '0 de 3')
  })
})

export {}
